const stats = msg.payload;
if (!stats || typeof stats !== 'object' || Array.isArray(stats)) return null;

const allowed = [
    'cpu_pct', 'mem_used_kb', 'mem_total_kb', 'mem_pct',
    'swap_used_kb', 'swap_total_kb',
    'load1', 'load5', 'load15', 'uptime_s', 'temp_c',
    'disk_used_root_kb', 'disk_total_root_kb',
    'disk_avail_root_kb', 'disk_pct_root',
    'rx_bytes', 'tx_bytes'
];

function statName(key) {
    return key.replace(/_/g, ' ').replace(/\b\w/g, c => c.toUpperCase());
}

const values = [];
for (const key of allowed) {
    const value = Number(stats[key]);
    if (!Number.isFinite(value)) continue;
    values.push(`('Master Closet Pi', '${statName(key)}', '${value}')`);
}

if (!values.length) return null;
msg.topic = 'INSERT INTO DeviceMonitoring(DeviceNM, StatNM, StatNBR) VALUES ' + values.join(', ') + ';';
return msg;

// Master closet satellite heartbeat. Output 1 feeds the offline trigger
// (every sample re-arms it); output 2 sends a recovery push once after an outage.
const stats = msg.payload || {};
const wasDown = flow.get('masterClosetDown') === true;
flow.set('masterClosetLastSeen', Date.now());
if (!wasDown) return [msg, null];
flow.set('masterClosetDown', false);
const up = Number(stats.uptime_s);
const upTxt = Number.isFinite(up) ? `${Math.round(up / 60)} min` : 'unknown';
return [msg, {
    topic: 'Master Closet Pi back online',
    payload: `Master closet satellite is publishing again (uptime ${upTxt}, ${stats.temp_c ?? '?'} C, IP 192.168.10.24).`,
    priority: 0
}];

// Fires when the trigger node has seen no sample for 5 minutes.
const last = flow.get('masterClosetLastSeen');
const lastTxt = last
    ? new Date(last).toLocaleString('en-US', { timeZone: 'America/Denver', hour12: true })
    : 'unknown';
flow.set('masterClosetDown', true);
return {
    topic: 'Master Closet Pi OFFLINE',
    payload: `No metrics from the master closet voice satellite for 5 min. Last sample ${lastTxt} MT. Check power / Wi-Fi at 192.168.10.24 (shelf next to the LED controller).`,
    priority: 0
};
